package com.volna.inventory_service.service;import com.volna.inventory_service.dto.vendor.*;import com.volna.inventory_service.entity.InventoryVendor;import com.volna.inventory_service.exception.ResourceNotFoundException;import com.volna.inventory_service.repository.InventoryVendorRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service @Transactional public class InventoryVendorService{private final InventoryVendorRepository repo;private final InventoryRestaurantAccessService access;public InventoryVendorService(InventoryVendorRepository r,InventoryRestaurantAccessService a){repo=r;access=a;}public Page<VendorResponse> all(UUID u,Pageable p){return repo.findByRestaurantId(access.restaurant(u),p).map(this::map);}public VendorResponse get(UUID u,Long id){return map(find(u,id));}public VendorResponse create(UUID u,CreateVendorRequest q){InventoryVendor x=new InventoryVendor();x.setRestaurantId(access.restaurant(u));x.setName(q.getName());x.setContactName(q.getContactName());x.setPhone(q.getPhone());x.setEmail(q.getEmail());return map(repo.save(x));}public VendorResponse update(UUID u,Long id,UpdateVendorRequest q){InventoryVendor x=find(u,id);x.setName(q.getName());x.setContactName(q.getContactName());x.setPhone(q.getPhone());x.setEmail(q.getEmail());if(q.getActive()!=null)x.setActive(q.getActive());return map(repo.save(x));}public void delete(UUID u,Long id){repo.delete(find(u,id));}private InventoryVendor find(UUID u,Long id){return repo.findByIdAndRestaurantId(id,access.restaurant(u)).orElseThrow(()->new ResourceNotFoundException("Vendor not found"));}private VendorResponse map(InventoryVendor x){return new VendorResponse(x.getId(),x.getName(),x.getContactName(),x.getPhone(),x.getEmail(),x.isActive());}}
